public class Demo3 {
    public static void main(String[] args) {
        new Outer().greet();
    }
}

class Outer {
    void greet() {
        int y = 5;
        y++;

        class Local {
            void sayHello() {
                System.out.println(y);
            }
        }

        Local local = new Local();
        local.sayHello();
    }
}

class Outer {
    int x = 10;

    class Inner {
        int x = 20;

        void show(int x) {
            System.out.println(x + " " + this.x + " " + Outer.this.x);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Outer outer = new Outer();
        Outer.Inner inner = outer.new Inner();
        inner.show(30);
    }
}

class Person {
    void introduce() {
        System.out.println("Hi, I am a person");
    }
}

public class Demo4 {
    public static void main(String[] args) {
        Person p2 = new Person() {
            String name = "Aditya";

            @Override
            void introduce() {
                greet();
                System.out.println("Hi, I am " + name);
            }

            void greet() {
                System.out.println("Hello");
            }
        };

        p2.introduce();
        p2.greet();   // added line
    }
}
